using System;
using System.Collections.Generic;
using System.Runtime.CompilerServices;
using System.Text.RegularExpressions;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Xaml.Controls.Primitives;
using Microsoft.UI.Xaml.Documents;
using Microsoft.UI.Xaml.Media;
using CommunityToolkit.WinUI.UI.Controls;

namespace StormSwitchBox.Services
{
    public readonly record struct L10nEntry(string En, string De, string Fr, string Zh, string Ko, string Ja, string Es, string It, string Pt, string Hi);

    public partial class LocalizationService
    {
        private readonly ConditionalWeakTable<object, Dictionary<string, (string OrigRu, string LastApplied)>> _originalTexts = new();
        private readonly List<WeakReference<DependencyObject>> _registeredRoots = new();

        public void RegisterRoot(DependencyObject? root)
        {
            if (root == null) return;
            lock (_registeredRoots)
            {
                _registeredRoots.RemoveAll(wr => !wr.TryGetTarget(out var t) || ReferenceEquals(t, root));
                _registeredRoots.Add(new WeakReference<DependencyObject>(root));
            }
            TranslateRoot(root);
        }

        public void UnregisterRoot(DependencyObject? root)
        {
            if (root == null) return;
            lock (_registeredRoots)
            {
                _registeredRoots.RemoveAll(wr => !wr.TryGetTarget(out var t) || ReferenceEquals(t, root));
            }
        }

        public void TranslateRegisteredRoots()
        {
            List<DependencyObject> aliveRoots;
            lock (_registeredRoots)
            {
                _registeredRoots.RemoveAll(wr => !wr.TryGetTarget(out _));
                aliveRoots = new List<DependencyObject>(_registeredRoots.Count);
                foreach (var wr in _registeredRoots)
                {
                    if (wr.TryGetTarget(out var r))
                    {
                        aliveRoots.Add(r);
                    }
                }
            }

            foreach (var root in aliveRoots)
            {
                try
                {
                    TranslateRoot(root);
                }
                catch { }
            }
        }

        private Dictionary<string, string>? _ruToKey;
        private Dictionary<string, string> RuToKey
        {
            get
            {
                if (_ruToKey == null)
                {
                    _ruToKey = new Dictionary<string, string>(StringComparer.Ordinal);
                    if (_strings.TryGetValue("ru", out var ruDict))
                    {
                        foreach (var kvp in ruDict)
                        {
                            if (!string.IsNullOrEmpty(kvp.Value) && !_ruToKey.ContainsKey(kvp.Value))
                            {
                                _ruToKey[kvp.Value] = kvp.Key;
                            }
                        }
                    }
                }
                return _ruToKey;
            }
        }

        private Dictionary<string, string>? _anyTranslatedToRu;
        private Dictionary<string, string> AnyTranslatedToRu
        {
            get
            {
                if (_anyTranslatedToRu == null)
                {
                    var dict = new Dictionary<string, string>(StringComparer.Ordinal);
                    foreach (var kvp in _directTranslations)
                    {
                        string ru = kvp.Key;
                        var e = kvp.Value;
                        AddReverse(dict, e.En, ru);
                        AddReverse(dict, e.De, ru);
                        AddReverse(dict, e.Fr, ru);
                        AddReverse(dict, e.Zh, ru);
                        AddReverse(dict, e.Ko, ru);
                        AddReverse(dict, e.Ja, ru);
                        AddReverse(dict, e.Es, ru);
                        AddReverse(dict, e.It, ru);
                        AddReverse(dict, e.Pt, ru);
                        AddReverse(dict, e.Hi, ru);
                    }

                    if (_strings.TryGetValue("ru", out var ruDict))
                    {
                        foreach (var langKvp in _strings)
                        {
                            if (langKvp.Key == "ru") continue;
                            foreach (var strKvp in langKvp.Value)
                            {
                                if (ruDict.TryGetValue(strKvp.Key, out var ruVal) && !string.IsNullOrEmpty(ruVal))
                                {
                                    AddReverse(dict, strKvp.Value, ruVal);
                                }
                            }
                        }
                    }
                    _anyTranslatedToRu = dict;
                }
                return _anyTranslatedToRu;
            }
        }

        private static void AddReverse(Dictionary<string, string> dict, string? val, string ru)
        {
            if (!string.IsNullOrWhiteSpace(val) && !dict.ContainsKey(val))
            {
                dict[val] = ru;
            }
        }

        public string TranslateText(string? text)
        {
            if (string.IsNullOrEmpty(text)) return text ?? "";

            if (_currentLanguage == "ru")
            {
                return text;
            }

            if (_directTranslations.TryGetValue(text, out var entry))
            {
                return GetLocalizedFromEntry(in entry, _currentLanguage);
            }

            string trimmed = text.Trim();
            if (trimmed.Length != text.Length && _directTranslations.TryGetValue(trimmed, out var entryTrimmed))
            {
                string trans = GetLocalizedFromEntry(in entryTrimmed, _currentLanguage);
                int leadWs = 0;
                while (leadWs < text.Length && char.IsWhiteSpace(text[leadWs])) leadWs++;
                int trailWs = 0;
                while (trailWs < text.Length && char.IsWhiteSpace(text[text.Length - 1 - trailWs])) trailWs++;
                return new string(' ', leadWs) + trans + new string(' ', trailWs);
            }

            if (RuToKey.TryGetValue(text, out var key) || RuToKey.TryGetValue(trimmed, out key))
            {
                if (_strings.TryGetValue(_currentLanguage, out var langDict) && langDict.TryGetValue(key, out var val))
                {
                    return val;
                }
            }

            string dyn = TranslateDynamicPattern(text, _currentLanguage);
            if (dyn != text)
            {
                return dyn;
            }

            return text;
        }

        private static string GetLocalizedFromEntry(in L10nEntry entry, string lang) => lang switch
        {
            "en" => entry.En,
            "de" => entry.De,
            "fr" => entry.Fr,
            "zh" => entry.Zh,
            "ko" => entry.Ko,
            "ja" => entry.Ja,
            "es" => entry.Es,
            "it" => entry.It,
            "pt" => entry.Pt,
            "hi" => entry.Hi,
            _ => entry.En
        };

        public void TranslateRoot(DependencyObject? root)
        {
            if (root == null) return;
            var visited = new HashSet<object>(ReferenceEqualityComparer.Instance);
            TraverseElement(root, visited);
        }

        private void TraverseElement(object? node, HashSet<object> visited)
        {
            if (node == null || !visited.Add(node)) return;

            if (node is UIElement uie)
            {
                var toolTipObj = ToolTipService.GetToolTip(uie);
                if (toolTipObj is string strTip)
                {
                    TranslateProp(uie, "ToolTip", strTip, val => ToolTipService.SetToolTip(uie, val));
                }
                else if (toolTipObj is ToolTip tt && tt.Content is string ttStr)
                {
                    TranslateProp(tt, "Content", ttStr, val => tt.Content = val);
                }

                if (uie.ContextFlyout != null)
                {
                    TraverseFlyout(uie.ContextFlyout, visited);
                }
            }

            switch (node)
            {
                case ContentDialog cd:
                    if (cd.Title is string titleStr)
                    {
                        TranslateProp(cd, "Title", titleStr, val => cd.Title = val);
                    }
                    if (!string.IsNullOrEmpty(cd.PrimaryButtonText))
                    {
                        TranslateProp(cd, "PrimaryButtonText", cd.PrimaryButtonText, val => cd.PrimaryButtonText = val);
                    }
                    if (!string.IsNullOrEmpty(cd.SecondaryButtonText))
                    {
                        TranslateProp(cd, "SecondaryButtonText", cd.SecondaryButtonText, val => cd.SecondaryButtonText = val);
                    }
                    if (!string.IsNullOrEmpty(cd.CloseButtonText))
                    {
                        TranslateProp(cd, "CloseButtonText", cd.CloseButtonText, val => cd.CloseButtonText = val);
                    }
                    if (cd.Content is DependencyObject cdContent)
                    {
                        TraverseElement(cdContent, visited);
                    }
                    break;

                case TabViewItem tvi:
                    if (tvi.Header is string tviHeader)
                    {
                        TranslateProp(tvi, "Header", tviHeader, val => tvi.Header = val);
                    }
                    if (tvi.Content is string tviContentStr)
                    {
                        TranslateProp(tvi, "Content", tviContentStr, val => tvi.Content = val);
                    }
                    else if (tvi.Content is DependencyObject tviContentObj)
                    {
                        TraverseElement(tviContentObj, visited);
                    }
                    break;

                case AppBarButton abb:
                    if (!string.IsNullOrEmpty(abb.Label))
                    {
                        TranslateProp(abb, "Label", abb.Label, val => abb.Label = val);
                    }
                    break;

                case Expander exp:
                    if (exp.Header is string expH)
                    {
                        TranslateProp(exp, "Header", expH, val => exp.Header = val);
                    }
                    else if (exp.Header is DependencyObject hObj)
                    {
                        TraverseElement(hObj, visited);
                    }
                    if (exp.Content is DependencyObject cObj)
                    {
                        TraverseElement(cObj, visited);
                    }
                    break;

                case TextBlock tb:
                    if (tb.Inlines != null && tb.Inlines.Count > 1)
                    {
                        foreach (var inline in tb.Inlines)
                        {
                            if (inline is Run run && !string.IsNullOrEmpty(run.Text))
                            {
                                TranslateProp(run, "Text", run.Text, val => run.Text = val);
                            }
                        }
                    }
                    else if (!string.IsNullOrEmpty(tb.Text))
                    {
                        TranslateProp(tb, "Text", tb.Text, val => tb.Text = val);
                    }
                    break;

                case TextBox tbox:
                    if (tbox.Header is string tbh)
                    {
                        TranslateProp(tbox, "Header", tbh, val => tbox.Header = val);
                    }
                    else if (tbox.Header is DependencyObject tbHObj)
                    {
                        TraverseElement(tbHObj, visited);
                    }
                    if (!string.IsNullOrEmpty(tbox.PlaceholderText))
                    {
                        TranslateProp(tbox, "PlaceholderText", tbox.PlaceholderText, val => tbox.PlaceholderText = val);
                    }
                    break;

                case AutoSuggestBox asb:
                    if (asb.Header is string asbH)
                    {
                        TranslateProp(asb, "Header", asbH, val => asb.Header = val);
                    }
                    if (!string.IsNullOrEmpty(asb.PlaceholderText))
                    {
                        TranslateProp(asb, "PlaceholderText", asb.PlaceholderText, val => asb.PlaceholderText = val);
                    }
                    break;

                case NumberBox nb:
                    if (nb.Header is string nbh)
                    {
                        TranslateProp(nb, "Header", nbh, val => nb.Header = val);
                    }
                    else if (nb.Header is DependencyObject nbHObj)
                    {
                        TraverseElement(nbHObj, visited);
                    }
                    if (!string.IsNullOrEmpty(nb.PlaceholderText))
                    {
                        TranslateProp(nb, "PlaceholderText", nb.PlaceholderText, val => nb.PlaceholderText = val);
                    }
                    break;

                case ComboBox cb:
                    if (cb.Header is string cbh)
                    {
                        TranslateProp(cb, "Header", cbh, val => cb.Header = val);
                    }
                    else if (cb.Header is DependencyObject cbHObj)
                    {
                        TraverseElement(cbHObj, visited);
                    }
                    if (!string.IsNullOrEmpty(cb.PlaceholderText))
                    {
                        TranslateProp(cb, "PlaceholderText", cb.PlaceholderText, val => cb.PlaceholderText = val);
                    }
                    break;

                case ToggleSwitch ts:
                    if (ts.Header is string tsh)
                    {
                        TranslateProp(ts, "Header", tsh, val => ts.Header = val);
                    }
                    else if (ts.Header is DependencyObject tsHObj)
                    {
                        TraverseElement(tsHObj, visited);
                    }
                    if (ts.OnContent is string onStr)
                    {
                        TranslateProp(ts, "OnContent", onStr, val => ts.OnContent = val);
                    }
                    if (ts.OffContent is string offStr)
                    {
                        TranslateProp(ts, "OffContent", offStr, val => ts.OffContent = val);
                    }
                    break;

                case TeachingTip tt:
                    if (!string.IsNullOrEmpty(tt.Title))
                    {
                        TranslateProp(tt, "Title", tt.Title, val => tt.Title = val);
                    }
                    if (!string.IsNullOrEmpty(tt.Subtitle))
                    {
                        TranslateProp(tt, "Subtitle", tt.Subtitle, val => tt.Subtitle = val);
                    }
                    break;

                case Button btn:
                    if (btn.Content is string btnContent)
                    {
                        TranslateProp(btn, "Content", btnContent, val => btn.Content = val);
                    }
                    if (btn.Flyout != null)
                    {
                        TraverseFlyout(btn.Flyout, visited);
                    }
                    break;

                case CheckBox chk:
                    if (chk.Content is string chkContent)
                    {
                        TranslateProp(chk, "Content", chkContent, val => chk.Content = val);
                    }
                    break;

                case RadioButton rb:
                    if (rb.Content is string rbContent)
                    {
                        TranslateProp(rb, "Content", rbContent, val => rb.Content = val);
                    }
                    break;

                case MenuFlyoutItem mfi:
                    if (!string.IsNullOrEmpty(mfi.Text))
                    {
                        TranslateProp(mfi, "Text", mfi.Text, val => mfi.Text = val);
                    }
                    break;



                case MenuFlyoutSubItem mfsi:
                    if (!string.IsNullOrEmpty(mfsi.Text))
                    {
                        TranslateProp(mfsi, "Text", mfsi.Text, val => mfsi.Text = val);
                    }
                    foreach (var sub in mfsi.Items)
                    {
                        TraverseElement(sub, visited);
                    }
                    break;



                case InfoBar ib:
                    if (!string.IsNullOrEmpty(ib.Title))
                    {
                        TranslateProp(ib, "Title", ib.Title, val => ib.Title = val);
                    }
                    if (!string.IsNullOrEmpty(ib.Message))
                    {
                        TranslateProp(ib, "Message", ib.Message, val => ib.Message = val);
                    }
                    break;
            }

            if (node is DependencyObject dobj)
            {
                int count = VisualTreeHelper.GetChildrenCount(dobj);
                for (int i = 0; i < count; i++)
                {
                    var child = VisualTreeHelper.GetChild(dobj, i);
                    TraverseElement(child, visited);
                }
            }
        }

        private void TraverseFlyout(FlyoutBase flyout, HashSet<object> visited)
        {
            if (!visited.Add(flyout)) return;

            if (flyout is MenuFlyout mf)
            {
                foreach (var item in mf.Items)
                {
                    TraverseElement(item, visited);
                }
            }
            else if (flyout is Flyout f && f.Content != null)
            {
                TraverseElement(f.Content, visited);
            }
        }

        private void TranslateProp(object target, string propertyName, string? currentVal, Action<string> setter)
        {
            if (string.IsNullOrEmpty(currentVal)) return;

            var map = _originalTexts.GetOrCreateValue(target);
            if (map.TryGetValue(propertyName, out var state))
            {
                if (string.Equals(currentVal, state.LastApplied, StringComparison.Ordinal))
                {
                    string trans = TranslateText(state.OrigRu);
                    if (trans != currentVal)
                    {
                        setter(trans);
                        map[propertyName] = (state.OrigRu, trans);
                    }
                }
                else
                {
                    string clean = currentVal.Trim();
                    string newOrigRu = ContainsCyrillic(currentVal)
                        ? currentVal
                        : (AnyTranslatedToRu.TryGetValue(clean, out var ru) ? ru : currentVal);

                    string trans = TranslateText(newOrigRu);
                    if (trans != currentVal)
                    {
                        setter(trans);
                        map[propertyName] = (newOrigRu, trans);
                    }
                    else
                    {
                        map[propertyName] = (newOrigRu, currentVal);
                    }
                }
            }
            else
            {
                string clean = currentVal.Trim();
                string origRu = ContainsCyrillic(currentVal)
                    ? currentVal
                    : (AnyTranslatedToRu.TryGetValue(clean, out var ru) ? ru : currentVal);

                string trans = TranslateText(origRu);
                if (trans != currentVal)
                {
                    setter(trans);
                    map[propertyName] = (origRu, trans);
                }
                else
                {
                    map[propertyName] = (origRu, currentVal);
                }
            }
        }

        private static bool ContainsCyrillic(string s)
        {
            for (int i = 0; i < s.Length; i++)
            {
                char c = s[i];
                if (c >= '\u0400' && c <= '\u04FF') return true;
            }
            return false;
        }

        public string TranslateDynamicPattern(string text, string lang)
        {
            if (string.IsNullOrEmpty(text) || lang == "ru") return text;

            // 1. Queue summary: "В списке: {0} • Качается: {1} • В очереди: {2} • Готово: {3}"
            var mQueue = Regex.Match(text, @"^В списке:\s*(\d+)\s*•\s*Качается:\s*(\d+)\s*•\s*В очереди:\s*(\d+)\s*•\s*Готово:\s*(\d+)$");
            if (mQueue.Success)
            {
                string a = mQueue.Groups[1].Value, b = mQueue.Groups[2].Value, c = mQueue.Groups[3].Value, d = mQueue.Groups[4].Value;
                return lang switch
                {
                    "en" => $"In list: {a} • Downloading: {b} • In queue: {c} • Done: {d}",
                    "de" => $"In Liste: {a} • Wird geladen: {b} • In Warteschlange: {c} • Fertig: {d}",
                    "fr" => $"Dans la liste : {a} • En cours : {b} • En file : {c} • Terminé : {d}",
                    "zh" => $"列表中: {a} • 下载中: {b} • 队列中: {c} • 已完成: {d}",
                    "ko" => $"목록: {a} • 다운로드 중: {b} • 대기열: {c} • 완료: {d}",
                    "ja" => $"リスト内: {a} • ダウンロード中: {b} • キュー内: {c} • 完了: {d}",
                    "es" => $"En lista: {a} • Descargando: {b} • En cola: {c} • Listo: {d}",
                    "it" => $"In elenco: {a} • In download: {b} • In coda: {c} • Completato: {d}",
                    "pt" => $"Na lista: {a} • Baixando: {b} • Na fila: {c} • Concluído: {d}",
                    "hi" => $"सूची में: {a} • डाउनलोड हो रहा है: {b} • कतार में: {c} • पूर्ण: {d}",
                    _ => text
                };
            }

            // 2. File and link badges: "Файлы: {0} • Ссылки: {1}"
            var mFilesLinks = Regex.Match(text, @"^Файлы:\s*(\d+)\s*•\s*Ссылки:\s*(\d+)$");
            if (mFilesLinks.Success)
            {
                string f = mFilesLinks.Groups[1].Value, l = mFilesLinks.Groups[2].Value;
                return lang switch
                {
                    "en" => $"Files: {f} • Links: {l}",
                    "de" => $"Dateien: {f} • Links: {l}",
                    "fr" => $"Fichiers : {f} • Liens : {l}",
                    "zh" => $"文件: {f} • 链接: {l}",
                    "ko" => $"파일: {f} • 링크: {l}",
                    "ja" => $"ファイル: {f} • リンク: {l}",
                    "es" => $"Archivos: {f} • Enlaces: {l}",
                    "it" => $"File: {f} • Link: {l}",
                    "pt" => $"Arquivos: {f} • Links: {l}",
                    "hi" => $"फ़ाइलें: {f} • लिंक: {l}",
                    _ => text
                };
            }

            // 3. "{0} файлов • {1}" or "{0} файла • {1}"
            var mFilesDot = Regex.Match(text, @"^(\d+)\s*(?:файлов|файла|файл)\s*•\s*(.+)$");
            if (mFilesDot.Success)
            {
                string count = mFilesDot.Groups[1].Value, rest = mFilesDot.Groups[2].Value;
                string restTr = TranslateText(rest);
                return lang switch
                {
                    "en" => $"{count} files • {restTr}",
                    "de" => $"{count} Dateien • {restTr}",
                    "fr" => $"{count} fichiers • {restTr}",
                    "zh" => $"{count} 个文件 • {restTr}",
                    "ko" => $"{count}개 파일 • {restTr}",
                    "ja" => $"{count} 個のファイル • {restTr}",
                    "es" => $"{count} archivos • {restTr}",
                    "it" => $"{count} file • {restTr}",
                    "pt" => $"{count} arquivos • {restTr}",
                    "hi" => $"{count} फ़ाइलें • {restTr}",
                    _ => text
                };
            }

            // 4. "{0} файлов" / "{0} файла" / "{0} файл"
            var mFiles = Regex.Match(text, @"^(\d+)\s*(?:файлов|файла|файл)$");
            if (mFiles.Success)
            {
                string count = mFiles.Groups[1].Value;
                return lang switch
                {
                    "en" => count == "1" ? "1 file" : $"{count} files",
                    "de" => count == "1" ? "1 Datei" : $"{count} Dateien",
                    "fr" => count == "1" ? "1 fichier" : $"{count} fichiers",
                    "zh" => $"{count} 个文件",
                    "ko" => $"{count}개 파일",
                    "ja" => $"{count} 個のファイル",
                    "es" => count == "1" ? "1 archivo" : $"{count} archivos",
                    "it" => $"{count} file",
                    "pt" => count == "1" ? "1 arquivo" : $"{count} arquivos",
                    "hi" => $"{count} फ़ाइलें",
                    _ => text
                };
            }

            // 5. "выбрано {0} из {1}" / "Выбрано {0} из {1}"
            var mSelOf = Regex.Match(text, @"^(?:[Вв]ыбрано)\s*(\d+)\s*из\s*(\d+)$");
            if (mSelOf.Success)
            {
                string a = mSelOf.Groups[1].Value, b = mSelOf.Groups[2].Value;
                return lang switch
                {
                    "en" => $"Selected {a} of {b}",
                    "de" => $"{a} von {b} ausgewählt",
                    "fr" => $"{a} sur {b} sélectionné(s)",
                    "zh" => $"已选择 {a} / {b}",
                    "ko" => $"{b}개 중 {a}개 선택됨",
                    "ja" => $"{b} 件中 {a} 件選択済み",
                    "es" => $"Seleccionado {a} de {b}",
                    "it" => $"Selezionato {a} di {b}",
                    "pt" => $"Selecionado {a} de {b}",
                    "hi" => $"{b} में से {a} चयनित",
                    _ => text
                };
            }

            // 6. "Выбрано: {0}" / "выбрано: {0}"
            var mSelColon = Regex.Match(text, @"^(?:[Вв]ыбрано):\s*(\d+)$");
            if (mSelColon.Success)
            {
                string a = mSelColon.Groups[1].Value;
                return lang switch
                {
                    "en" => $"Selected: {a}",
                    "de" => $"Ausgewählt: {a}",
                    "fr" => $"Sélectionné : {a}",
                    "zh" => $"已选择: {a}",
                    "ko" => $"선택됨: {a}",
                    "ja" => $"選択済み: {a}",
                    "es" => $"Seleccionado: {a}",
                    "it" => $"Selezionato: {a}",
                    "pt" => $"Selecionado: {a}",
                    "hi" => $"चयनित: {a}",
                    _ => text
                };
            }

            // 7. "Ссылок в теме и обсуждении: {0} (выбрано: {1})"
            var mLinksThread = Regex.Match(text, @"^Ссылок в теме и обсуждении:\s*(\d+)\s*\(выбрано:\s*(\d+)\)$");
            if (mLinksThread.Success)
            {
                string a = mLinksThread.Groups[1].Value, b = mLinksThread.Groups[2].Value;
                return lang switch
                {
                    "en" => $"Links in thread and discussion: {a} (selected: {b})",
                    "de" => $"Links im Thread und Diskussion: {a} (ausgewählt: {b})",
                    "fr" => $"Liens dans le sujet et la discussion : {a} (sélectionnés : {b})",
                    "zh" => $"主题与讨论中的链接: {a} (已选: {b})",
                    "ko" => $"스레드 및 토론의 링크: {a} (선택됨: {b})",
                    "ja" => $"スレッドと議論のリンク: {a} (選択済み: {b})",
                    "es" => $"Enlaces en el tema y debate: {a} (seleccionados: {b})",
                    "it" => $"Link nella discussione: {a} (selezionati: {b})",
                    "pt" => $"Links no tópico e discussão: {a} (selecionados: {b})",
                    "hi" => $"चर्चा में लिंक: {a} (चयनित: {b})",
