                };
            }

            // 9. "Игра #{0}" / "ИГРА #{0}"
            var mGameSlot = Regex.Match(text, @"^(?:[Ии]гра|ИГРА)\s*#(\d+)$");
            if (mGameSlot.Success)
            {
                string a = mGameSlot.Groups[1].Value;
                return lang switch
                {
                    "en" => $"Game #{a}",
                    "de" => $"Spiel #{a}",
