                    "es" => $"Juego #{a}",
                    "it" => $"Gioco #{a}",
                    "pt" => $"Jogo #{a}",
                    "hi" => $"गेम #{a}",
                    _ => text
                };
            }

            // 10. "{0} из {1} задач"
            var mTasksOf = Regex.Match(text, @"^(\d+)\s*из\s*(\d+)\s*задач$");
            if (mTasksOf.Success)
            {
                string a = mTasksOf.Groups[1].Value, b = mTasksOf.Groups[2].Value;
                return lang switch
                {
                    "en" => $"{a} of {b} tasks",
                    "de" => $"{a} von {b} Aufgaben",
                    "fr" => $"{a} sur {b} tâches",
                    "zh" => $"{a} / {b} 个任务",
                    "ko" => $"{b}개 중 {a}개 작업",
                    "ja" => $"{b} 件中 {a} 件のタスク",
                    "es" => $"{a} de {b} tareas",
                    "it" => $"{a} di {b} attività",
                    "pt" => $"{a} de {b} tarefas",
                    "hi" => $"{b} में से {a} कार्य",
                    _ => text
                };
            }

            // 11. Torrent stats: "Скорость скачивания: {0}"
            var mSpeed = Regex.Match(text, @"^Скорость скачивания:\s*(.+)$");
            if (mSpeed.Success)
            {
                string spd = TranslateDynamicPattern(mSpeed.Groups[1].Value, lang);
                return lang switch
                {
                    "en" => $"Download speed: {spd}",
                    "de" => $"Download-Geschwindigkeit: {spd}",
                    "fr" => $"Vitesse de téléchargement : {spd}",
                    "zh" => $"下载速度: {spd}",
                    "ko" => $"다운로드 속도: {spd}",
                    "ja" => $"ダウンロード速度: {spd}",
                    "es" => $"Velocidad de descarga: {spd}",
                    "it" => $"Velocità di download: {spd}",
                    "pt" => $"Velocidade de download: {spd}",
                    "hi" => $"डाउनलोड गति: {spd}",
                    _ => text
                };
            }

            // 12. "Сиды: {0}"
            var mSeeds = Regex.Match(text, @"^Сиды:\s*(\d+)$");
            if (mSeeds.Success)
            {
                string s = mSeeds.Groups[1].Value;
                return lang switch
                {
                    "en" => $"Seeds: {s}",
                    "de" => $"Seeds: {s}",
                    "fr" => $"Sources : {s}",
                    "zh" => $"做种: {s}",
                    "ko" => $"시드: {s}",
                    "ja" => $"シード: {s}",
                    "es" => $"Semillas: {s}",
                    "it" => $"Seed: {s}",
                    "pt" => $"Seeds: {s}",
                    "hi" => $"सीड्स: {s}",
                    _ => text
                };
            }

            // 13. "Пиры: {0}"
            var mPeers = Regex.Match(text, @"^Пиры:\s*(\d+)$");
            if (mPeers.Success)
            {
                string p = mPeers.Groups[1].Value;
                return lang switch
                {
                    "en" => $"Peers: {p}",
                    "de" => $"Peers: {p}",
                    "fr" => $"Pairs : {p}",
                    "zh" => $"同伴: {p}",
                    "ko" => $"피어: {p}",
