            // 14. "(в рое: {0})"
            var mSwarm = Regex.Match(text, @"^\(в рое:\s*(\d+)\)$");
            if (mSwarm.Success)
            {
                string sw = mSwarm.Groups[1].Value;
                return lang switch
                {
                    "en" => $"(in swarm: {sw})",
                    "de" => $"(im Swarm: {sw})",
                    "fr" => $"(dans l'essaim : {sw})",
                    "zh" => $"(蜂群中: {sw})",
