                };
            }

            // 15. "Страница {0} из {1}"
            var mPage = Regex.Match(text, @"^Страница\s*(\d+)\s*из\s*(\d+)$");
            if (mPage.Success)
            {
                string a = mPage.Groups[1].Value, b = mPage.Groups[2].Value;
                return lang switch
                {
                    "en" => $"Page {a} of {b}",
                    "de" => $"Seite {a} von {b}",
                    "fr" => $"Page {a} sur {b}",
                    "zh" => $"第 {a} 页，共 {b} 页",
