                    "es" => $"Página {a} de {b}",
                    "it" => $"Pagina {a} di {b}",
                    "pt" => $"Página {a} de {b}",
                    "hi" => $"{b} में से पृष्ठ {a}",
                    _ => text
                };
            }

            // 16. "Обсуждение (стр. {0}, @{1})"
            var mDisc = Regex.Match(text, @"^Обсуждение\s*\(стр\.\s*(\d+),\s*@([^\)]+)\)$");
            if (mDisc.Success)
            {
                string a = mDisc.Groups[1].Value, b = mDisc.Groups[2].Value;
                return lang switch
                {
                    "en" => $"Discussion (p. {a}, @{b})",
                    "de" => $"Diskussion (S. {a}, @{b})",
                    "fr" => $"Discussion (p. {a}, @{b})",
                    "zh" => $"讨论 (第 {a} 页, @{b})",
                    "ko" => $"토론 ({a}페이지, @{b})",
                    "ja" => $"ディスカッション ({a} ページ, @{b})",
                    "es" => $"Discusión (pág. {a}, @{b})",
                    "it" => $"Discussione (pag. {a}, @{b})",
                    "pt" => $"Discussão (pág. {a}, @{b})",
                    "hi" => $"चर्चा (पृष्ठ {a}, @{b})",
                    _ => text
                };
            }

            // 17. Units: "100% Завершено"
            if (text == "100% Завершено")
            {
                return lang switch
                {
                    "en" => "100% Completed",
                    "de" => "100% Abgeschlossen",
                    "fr" => "100% Terminé",
                    "zh" => "100% 已完成",
                    "ko" => "100% 완료됨",
                    "ja" => "100% 完了",
                    "es" => "100% Completado",
                    "it" => "100% Completato",
                    "pt" => "100% Concluído",
                    "hi" => "100% पूर्ण",
                    _ => text
                };
            }

            // 18. Speed / size units: МБ/с, КБ/с, Б/с, ГБ, МБ, КБ
            if (text.EndsWith("МБ/с"))
            {
                string num = text[..^4].Trim();
                string u = lang == "fr" ? "Mo/s" : "MB/s";
                return $"{num} {u}";
            }
            if (text.EndsWith("КБ/с"))
            {
                string num = text[..^4].Trim();
                string u = lang == "fr" ? "Ko/s" : "KB/s";
                return $"{num} {u}";
            }
            if (text.EndsWith("Б/с"))
            {
                string num = text[..^3].Trim();
                string u = lang == "fr" ? "o/s" : "B/s";
                return $"{num} {u}";
            }
            if (text.EndsWith(" ГБ"))
            {
                string num = text[..^3].Trim();
                string u = lang switch { "ru" => "ГБ", "fr" => "Go", _ => "GB" };
                return $"{num} {u}";
            }
            if (text.EndsWith(" МБ"))
            {
                string num = text[..^3].Trim();
                string u = lang switch { "ru" => "МБ", "fr" => "Mo", _ => "MB" };
                return $"{num} {u}";
            }
            if (text.EndsWith(" КБ"))
            {
                string num = text[..^3].Trim();
                string u = lang switch { "ru" => "КБ", "fr" => "Ko", _ => "KB" };
                return $"{num} {u}";
            }

            // 19. Compiled C# interpolated {expr} templates from _directTranslations
            foreach (var tpl in CompiledTemplates)
            {
                var mTpl = tpl.Pattern.Match(text);
                if (mTpl.Success)
                {
                    var tplEntry = tpl.Entry;
                    string targetTpl = GetLocalizedFromEntry(in tplEntry, lang);
                    for (int i = 0; i < tpl.Placeholders.Length; i++)
                    {
                        string captured = mTpl.Groups[i + 1].Value;
                        string capturedTr = ContainsCyrillic(captured) ? TranslateText(captured) : captured;
                        targetTpl = targetTpl.Replace(tpl.Placeholders[i], capturedTr, StringComparison.Ordinal);
                    }
                    return targetTpl;
                }
            }

            return text;
        }

        private sealed record CompiledTemplate(Regex Pattern, string[] Placeholders, L10nEntry Entry);
        private List<CompiledTemplate>? _compiledTemplates;
        private List<CompiledTemplate> CompiledTemplates => _compiledTemplates ??= BuildCompiledTemplates();

        private List<CompiledTemplate> BuildCompiledTemplates()
        {
            var list = new List<CompiledTemplate>();
            var phRegex = new Regex(@"\{([^\}]+)\}");
            foreach (var kvp in _directTranslations)
            {
                string ruKey = kvp.Key;
                if (!ruKey.Contains('{') || !ruKey.Contains('}')) continue;
                var matches = phRegex.Matches(ruKey);
                if (matches.Count == 0) continue;

                var placeholders = new string[matches.Count];
                var sb = new System.Text.StringBuilder("^");
                int lastIdx = 0;
                for (int i = 0; i < matches.Count; i++)
                {
                    var m = matches[i];
                    if (m.Index > lastIdx)
                    {
                        sb.Append(Regex.Escape(ruKey.Substring(lastIdx, m.Index - lastIdx)));
                    }
                    placeholders[i] = m.Value;
                    sb.Append(i == matches.Count - 1 ? "(.+)" : "(.+?)");
                    lastIdx = m.Index + m.Length;
                }
                if (lastIdx < ruKey.Length)
                {
                    sb.Append(Regex.Escape(ruKey.Substring(lastIdx)));
                }
                sb.Append('$');

                list.Add(new CompiledTemplate(new Regex(sb.ToString(), RegexOptions.CultureInvariant | RegexOptions.Singleline), placeholders, kvp.Value));
            }
            list.Sort((a, b) => b.Pattern.ToString().Length.CompareTo(a.Pattern.ToString().Length));
            return list;
        }

