            ["Запуск операции из командной строки: Action={action}, Format={format}"] = new L10nEntry("Starting an operation from the command line: Action={action}, Format={format}", "Starten einer Operation über die Befehlszeile: Action={action}, Format={format}", "Lancer une opération depuis la ligne de commande : Action={action}, Format={format}", "从命令行启动操作：Action={action}，Format={format}", "명령줄에서 작업 시작: 작업={action}, 형식={format}", "コマンドラインから操作を開始する: Action={action}、Format={format}", "Iniciar una operación desde la línea de comando: Acción={action}, Formato={format}", "Avvio di un'operazione dalla riga di comando: Azione={action}, Formato={format}", "Iniciando uma operação na linha de comando: Action={action}, Format={format}", "कमांड लाइन से एक ऑपरेशन शुरू करना: Action={action}, Format={format}"),
            ["Запуск фоновой обработки очереди задач..."] = new L10nEntry("Starting background processing of the task queue...", "Hintergrundverarbeitung der Aufgabenwarteschlange wird gestartet...", "Démarrage du traitement en arrière-plan de la file d'attente des tâches...", "开始任务队列的后台处理...", "작업 대기열의 백그라운드 처리를 시작하는 중...", "タスクキューのバックグラウンド処理を開始しています...", "Iniciando procesamiento en segundo plano de la cola de tareas...", "Avvio dell'elaborazione in background della coda delle attività...", "Iniciando o processamento em segundo plano da fila de tarefas...", "कार्य कतार की पृष्ठभूमि प्रोसेसिंग प्रारंभ हो रही है..."),
            ["Запуск хоумбрю в Applet Mode (через Альбом) или несовместимый мод LayeredFS в atmosphere/contents/<TitleID>/."] = new L10nEntry("Running homebrew in Applet Mode (via Album) or incompatible LayeredFS mod in atmosphere/contents/<TitleID>/.", "Ausführen von Homebrew im Applet-Modus (über Album) oder inkompatibler LayeredFS-Mod in Atmosphäre/Inhalt/<Titel-ID>/.", "Exécution d'un homebrew en mode Applet (via Album) ou d'un mod LayeredFS incompatible dans atmosphère/contents/<TitleID>/.", "在 Applet 模式（通过专辑）或不兼容的 LayeredFS mod 中运行 homebrew 大气/内容/<TitleID>/。", "애플릿 모드(앨범을 통해)에서 홈브류를 실행하거나 분위기/콘텐츠/<TitleID>/에서 호환되지 않는 LayeredFS 모드를 실행합니다.", "アプレット モード (アルバム経由) で homebrew を実行しているか、atmosphere/contents/<TitleID>/ で互換性のない LayeredFS mod を実行しています。", "Ejecutando homebrew en modo Applet (a través de Álbum) o mod LayeredFS incompatible en atmósfera/contenidos/<TitleID>/.", "Esecuzione di homebrew in modalità Applet (tramite Album) o mod LayeredFS incompatibile in atmosfera/contents/<TitleID>/.", "Executando homebrew no modo Applet (via Álbum) ou mod LayeredFS incompatível em atmosfera/contents/<TitleID>/.", "एप्लेट मोड में होमब्रू चलाना (एल्बम के माध्यम से) या वातावरण/सामग्री/<TitleID>/ में असंगत लेयर्डएफएस मॉड।"),
            ["Запускайте хоумбрю через созданный NSP-форвардер (вкладка Homebrew) или с зажатой кнопкой R при старте игры."] = new L10nEntry("Launch homebrew through the created NSP forwarder (Homebrew tab) or by holding down the R button when starting the game.", "Starten Sie Homebrew über den erstellten NSP-Forwarder (Registerkarte „Homebrew“) oder indem Sie beim Starten des Spiels die R-Taste gedrückt halten.", "Lancez l'homebrew via le redirecteur NSP créé (onglet Homebrew) ou en maintenant enfoncé le bouton R au démarrage du jeu.", "通过创建的 NSP 转发器（Homebrew 选项卡）或启动游戏时按住 R 按钮启动 homebrew。", "생성된 NSP 포워더(Homebrew 탭)를 통해 홈브류를 실행하거나 게임을 시작할 때 R 버튼을 길게 눌러 홈브류를 실행하세요.", "作成した NSP フォワーダー (Homebrew タブ) から、またはゲーム開始時に R ボタンを押したままにして Homebrew を起動します。", "Inicie Homebrew a través del reenviador NSP creado (pestaña Homebrew) o manteniendo presionado el botón R al iniciar el juego.", "Avvia l'homebrew tramite il forwarder NSP creato (scheda Homebrew) o tenendo premuto il pulsante R all'avvio del gioco.", "Inicie o homebrew através do encaminhador NSP criado (guia Homebrew) ou mantendo pressionado o botão R ao iniciar o jogo.", "निर्मित एनएसपी फारवर्डर (होमब्रू टैब) के माध्यम से या गेम शुरू करते समय आर बटन दबाकर होमब्रू लॉन्च करें।"),
            ["Запустить все"] = new L10nEntry("Start All", "Alle starten", "Tout démarrer", "全部开始", "모두 실행", "すべて開始", "ejecutar todo", "Corri tutto", "Execute tudo", "सब चलाओ"),
